const body = $json.body ?? $json;
const required = ['reportId', 'targetType', 'targetId'];
for (const key of required) {
  if (!body[key]) {
    throw new Error(`Missing required field: ${key}`);
  }
}
const contentText = String(body.contentText ?? '').trim();
const description = String(body.description ?? '').trim();
const reasonLabel = String(body.reasonLabel ?? '').trim();
const reasonCode = String(body.reasonCode ?? '').trim();
const inputText = [
  `targetType: ${body.targetType}`,
  reasonCode ? `reasonCode: ${reasonCode}` : '',
  reasonLabel ? `reasonLabel: ${reasonLabel}` : '',
  description ? `reportDescription: ${description}` : '',
  contentText ? `reportedContent: ${contentText}` : '',
].filter(Boolean).join('\n');
const imageUrls = Array.isArray(body.imageUrls) ? body.imageUrls.filter(Boolean) : [];
const moderationInput = [{ type: 'text', text: inputText || `${body.targetType} report` }];
for (const imageUrl of imageUrls.slice(0, 10)) {
  moderationInput.push({ type: 'image_url', image_url: { url: imageUrl } });
}
return [{
  json: {
    report: body,
    openaiRequest: {
      model: $env.OPENAI_MODERATION_MODEL || 'omni-moderation-latest',
      input: moderationInput,
    },
  },
}];

const report = $('Validate And Build OpenAI Request').first().json.report;
const result = Array.isArray($json.results) ? $json.results[0] : undefined;
if (!result) {
  throw new Error('OpenAI moderation response does not contain results[0]');
}
const categories = result.categories ?? {};
const categoryScores = result.category_scores ?? {};
const labels = Object.entries(categories)
  .filter(([, flagged]) => Boolean(flagged))
  .map(([label]) => label);
const maxScore = Object.values(categoryScores).reduce((max, value) => {
  const numeric = Number(value);
  return Number.isFinite(numeric) ? Math.max(max, numeric) : max;
}, 0);
const score = Math.round(maxScore * 10000) / 100;
let decision = 'SAFE';
if (result.flagged || score >= 80) {
  decision = 'VIOLATION';
} else if (score >= 45 || labels.length > 0) {
  decision = 'NEEDS_REVIEW';
}
const explanation = labels.length > 0
  ? `OpenAI moderation flagged ${labels.join(', ')} with max score ${score}.`
  : `OpenAI moderation did not flag the content. Max score ${score}.`;
return [{
  json: {
    decision,
    score,
    labels,
    explanation,
    modelName: $json.model || $env.OPENAI_MODERATION_MODEL || 'omni-moderation-latest',
    rawCategories: {
      flagged: result.flagged,
      categories,
      category_scores: categoryScores,
      category_applied_input_types: result.category_applied_input_types ?? {},
      reportId: report.reportId,
      targetType: report.targetType,
      targetId: report.targetId,
    },
  },
}];
